-- ============================================================
-- njupt_physim 数据库完整导出（结构 + 数据）
-- 导入方式: mysql -u<用户> -p njupt_physim < njupt_physim_dump.sql
-- 注意: 目标库需先创建: CREATE DATABASE IF NOT EXISTS njupt_physim DEFAULT CHARSET utf8mb4;
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure + data for `clazzes`
-- ----------------------------
DROP TABLE IF EXISTS `clazzes`;
CREATE TABLE `clazzes` (
  `id` varchar(10) NOT NULL,
  `create_time` year DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- ----------------------------
-- Table structure + data for `comments`
-- ----------------------------
DROP TABLE IF EXISTS `comments`;
CREATE TABLE `comments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` varchar(10) NOT NULL,
  `resource_id` int NOT NULL,
  `time` datetime NOT NULL,
  `content` varchar(60) NOT NULL,
  `likes` int NOT NULL DEFAULT '0',
  `visible` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `idx_comments_resource_id` (`resource_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------
-- Table structure + data for `completions`
-- ----------------------------
DROP TABLE IF EXISTS `completions`;
CREATE TABLE `completions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `stu_id` varchar(10) NOT NULL,
  `clazz_id` varchar(10) NOT NULL,
  `task_id` int NOT NULL,
  `time` date NOT NULL,
  `score` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- ----------------------------
-- Table structure + data for `logs`
-- ----------------------------
DROP TABLE IF EXISTS `logs`;
CREATE TABLE `logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` varchar(10) NOT NULL,
  `log_type` enum('INFO','ERROR','WARN') NOT NULL,
  `message` varchar(50) NOT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------
-- Table structure + data for `permissions`
-- ----------------------------
DROP TABLE IF EXISTS `permissions`;
CREATE TABLE `permissions` (
  `id` int NOT NULL,
  `name` varchar(10) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------
-- Table structure + data for `replies`
-- ----------------------------
DROP TABLE IF EXISTS `replies`;
CREATE TABLE `replies` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` varchar(10) NOT NULL,
  `comment_id` int NOT NULL,
  `time` datetime NOT NULL,
  `content` varchar(60) NOT NULL,
  `likes` int NOT NULL DEFAULT '0',
  `visible` tinyint(1) NOT NULL DEFAULT '1',
  `replied_user_name` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_replies_comment_id` (`comment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------
-- Table structure + data for `reservations`
-- ----------------------------
DROP TABLE IF EXISTS `reservations`;
CREATE TABLE `reservations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `day` date NOT NULL,
  `slot` int NOT NULL,
  `reservation_count` int DEFAULT '0',
  `max_count` int NOT NULL DEFAULT '30',
  `is_active` int NOT NULL DEFAULT '1' COMMENT '当日此时段是否允许预约(1:允许 0:禁止)',
  PRIMARY KEY (`id`),
  CONSTRAINT `reservations_chk_1` CHECK ((`reservation_count` between 0 and 40))
) ENGINE=InnoDB AUTO_INCREMENT=538 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- ----------------------------
-- Table structure + data for `resources`
-- ----------------------------
DROP TABLE IF EXISTS `resources`;
CREATE TABLE `resources` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(20) NOT NULL,
  `create_time` date NOT NULL,
  `creater_id` varchar(10) NOT NULL,
  `coverImage` varchar(2048) NOT NULL,
  `url` varchar(2048) NOT NULL,
  `tag` varchar(20) NOT NULL,
  `content` varchar(30) NOT NULL,
  `likes` int NOT NULL DEFAULT '0',
  `easy_count` int NOT NULL DEFAULT '0',
  `hard_count` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `fk_resources_creater_id` (`creater_id`),
  CONSTRAINT `fk_resources_creater_id` FOREIGN KEY (`creater_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- ----------------------------
-- Table structure + data for `role_permission`
-- ----------------------------
DROP TABLE IF EXISTS `role_permission`;
CREATE TABLE `role_permission` (
  `role_id` int NOT NULL,
  `edit_users` int NOT NULL,
  `edit_resources` int NOT NULL,
  `use_resources` int NOT NULL,
  PRIMARY KEY (`role_id`),
  CONSTRAINT `role_permission_ibfk_1` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- ----------------------------
-- Table structure + data for `roles`
-- ----------------------------
DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles` (
  `id` int NOT NULL,
  `name` varchar(10) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- ----------------------------
-- Table structure + data for `stu_reservations`
-- ----------------------------
DROP TABLE IF EXISTS `stu_reservations`;
CREATE TABLE `stu_reservations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `stu_id` varchar(10) NOT NULL,
  `day` date NOT NULL,
  `slot` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- ----------------------------
-- Table structure + data for `sys_ip_blacklist`
-- ----------------------------
DROP TABLE IF EXISTS `sys_ip_blacklist`;
CREATE TABLE `sys_ip_blacklist` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `ip` varchar(32) NOT NULL COMMENT 'IP地址(支持精确/通配符/CIDR)',
  `reason` varchar(200) DEFAULT NULL COMMENT '封禁原因',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '状态(1:封禁中 0:已解封)',
  `ban_time` datetime DEFAULT NULL COMMENT '封禁时间',
  `unban_time` datetime DEFAULT NULL COMMENT '解封时间',
  `operator` varchar(50) DEFAULT NULL COMMENT '操作人(系统自动/管理员)',
  `create_date` datetime DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_ip` (`ip`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='IP黑名单';


-- ----------------------------
-- Table structure + data for `sys_log_error`
-- ----------------------------
DROP TABLE IF EXISTS `sys_log_error`;
CREATE TABLE `sys_log_error` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `error_info` text COMMENT '异常信息',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_date` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_create_date` (`create_date`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统异常日志表';


-- ----------------------------
-- Table structure + data for `sys_log_login`
-- ----------------------------
DROP TABLE IF EXISTS `sys_log_login`;
CREATE TABLE `sys_log_login` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `operation` tinyint unsigned DEFAULT NULL COMMENT '用户操作(0:用户登录; 1:用户退出)',
  `status` tinyint unsigned NOT NULL COMMENT '状态(0:失败; 1:成功; 2:账号已锁定)',
  `creator_name` varchar(50) DEFAULT NULL COMMENT '用户名',
  `create_date` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_create_date` (`create_date`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=122 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统登录日志';


-- ----------------------------
-- Table structure + data for `sys_log_operation`
-- ----------------------------
DROP TABLE IF EXISTS `sys_log_operation`;
CREATE TABLE `sys_log_operation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `operation` varchar(50) DEFAULT NULL COMMENT '用户操作',
  `request_uri` varchar(200) DEFAULT NULL COMMENT '请求URI',
  `request_method` varchar(20) DEFAULT NULL COMMENT '请求方式',
  `request_params` text COMMENT '请求参数',
  `request_time` int NOT NULL COMMENT '请求时长(毫秒)',
  `ip` varchar(32) DEFAULT NULL COMMENT '操作IP',
  `status` tinyint unsigned NOT NULL COMMENT '状态(0:失败; 1:成功)',
  `creator_name` varchar(50) DEFAULT NULL COMMENT '用户名',
  `creator` bigint DEFAULT NULL COMMENT '创建者',
  `create_date` datetime DEFAULT NULL COMMENT '创建时间',
  `type` varchar(1) DEFAULT NULL COMMENT '日志类型(0:系统事件 1:业务事件)',
  PRIMARY KEY (`id`),
  KEY `idx_create_date` (`create_date`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统操作日志';


-- ----------------------------
-- Table structure + data for `sys_log_root_event`
-- ----------------------------
DROP TABLE IF EXISTS `sys_log_root_event`;
CREATE TABLE `sys_log_root_event` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `begin_date` datetime DEFAULT NULL COMMENT '开始时间',
  `end_date` datetime DEFAULT NULL COMMENT '结束时间',
  `event_detail` varchar(200) DEFAULT NULL COMMENT '事件内容',
  `create_date` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_create_date` (`create_date`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='管理员事件管理';


-- ----------------------------
-- Table structure + data for `tasks`
-- ----------------------------
DROP TABLE IF EXISTS `tasks`;
CREATE TABLE `tasks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `teacher` varchar(10) NOT NULL,
  `clazz_id` varchar(10) NOT NULL,
  `exp_id` int NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `complete_count` int NOT NULL DEFAULT '0',
  `total_count` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_task_clazz_id` (`clazz_id`),
  KEY `fk_task_exp_name` (`exp_id`),
  CONSTRAINT `fk_task_clazz_id` FOREIGN KEY (`clazz_id`) REFERENCES `clazzes` (`id`),
  CONSTRAINT `fk_task_exp_name` FOREIGN KEY (`exp_id`) REFERENCES `resources` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- ----------------------------
-- Table structure + data for `user_clazz`
-- ----------------------------
DROP TABLE IF EXISTS `user_clazz`;
CREATE TABLE `user_clazz` (
  `clazz_id` varchar(10) NOT NULL,
  `user_id` varchar(10) NOT NULL,
  `role_id` int NOT NULL,
  PRIMARY KEY (`clazz_id`,`user_id`),
  KEY `fk_user_clazz_user_id` (`user_id`),
  KEY `fk_user_clazz_role_id` (`role_id`),
  CONSTRAINT `fk_user_clazz_clazz_id` FOREIGN KEY (`clazz_id`) REFERENCES `clazzes` (`id`),
  CONSTRAINT `fk_user_clazz_role_id` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`),
  CONSTRAINT `fk_user_clazz_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


-- ----------------------------
-- Table structure + data for `users`
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` varchar(10) NOT NULL,
  `name` varchar(10) NOT NULL,
  `account` varchar(10) NOT NULL,
  `password` varchar(20) NOT NULL,
  `create_time` date NOT NULL,
  `role_id` int NOT NULL,
  `avatar` varchar(255) NOT NULL,
  `college` varchar(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `role_id` (`role_id`),
  CONSTRAINT `users_ibfk_1` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


SET FOREIGN_KEY_CHECKS = 1;
